CREATE TABLE IF NOT EXISTS `gameobject_spawns` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'Unique Spawn Identifier',
  `min_build` int NOT NULL DEFAULT '12340',
  `max_build` int NOT NULL DEFAULT '12340',
  `entry` int unsigned NOT NULL DEFAULT '0' COMMENT 'Gameobject Identifier',
  `map` int unsigned NOT NULL DEFAULT '0' COMMENT 'Map Identifier',
  `phase` int unsigned NOT NULL DEFAULT '1' COMMENT 'Phase mask',
  `position_x` float NOT NULL DEFAULT '0',
  `position_y` float NOT NULL DEFAULT '0',
  `position_z` float NOT NULL DEFAULT '0',
  `orientation` float NOT NULL DEFAULT '0',
  `rotation0` float NOT NULL DEFAULT '0',
  `rotation1` float NOT NULL DEFAULT '0',
  `rotation2` float NOT NULL DEFAULT '0',
  `rotation3` float NOT NULL DEFAULT '0',
  `spawntimesecs` int NOT NULL DEFAULT '0',
  `state` int unsigned NOT NULL DEFAULT '0',
  `event_entry` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`,`min_build`),
  UNIQUE KEY `unique_index` (`id`,`min_build`) USING BTREE,
  KEY `Entry` (`entry`)
) ENGINE=MyISAM AUTO_INCREMENT=672429 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Spawn System';

